import React, {
	useState,
	useRef,
	useEffect
} from "react";



import "./MonthPicker.css";
import { SvgIcon_Cmpt } from ".";
import UseDelayInput from "../hooks/useDelayInput";


const Svg = SvgIcon_Cmpt();

const DropDwnPickerSearchComponent = ({init, onSelect,  lbl_empty, direction, background, color, width, func, extraParam }) => {
	
	const [list, setList] = useState([]);
	const [open, setOpen] = useState(false);
	const [searchQr, setSearchQ] = useState("");
	const showAct = useRef(false);
	const inputRef = useRef(null);

	let deferredInput = UseDelayInput(searchQr);


	useEffect(() => {
		if (!deferredInput) {
			setList([]);
		} else {
			fetchData(deferredInput);
		}
		
		return () => {
			//;
		};
	}, [deferredInput]);

	
	const fetchData = async (v) => {
		
		let res =  await func(v, extraParam);
	
		setList(res);
	}

	const handleSelection = (v) => {
		handleClick(v);
		
	}

	const handleClick = (v) => {
		if(showAct.current){
			showAct.current = false
			setOpen(false);
			
			if(v){
				onSelect(v);
			}
		}else if(!showAct.current){
			setOpen(true)
			setTimeout(() => {
				showAct.current = true
			}, 50);
		}
	};

	const handleInputSearch = async (e) => {
		setSearchQ(e.target.value);
	}


	const clearInputSearch = async (e) => {
		inputRef.current.value = "";
		fetchData("");
		onSelect(null);
		handleClick();
	}


	let labelInit = list && list?.filter(e=>e.id===init)?.[0];

	let dir = direction || "left";

	let _style = {
		"--color-pck":color?color:null,
		"--backColor-pck":background?background:null,
		"--width-pck":width?width:"130px",
	}

	return (
		<div  id={`drpdwn_click_outside`} open={open} style={_style} >
			<div className={"filter_month_btn _dsplFlx"} onClick={handleClick}>
				<div className="lbl date" >
						{labelInit?.label || lbl_empty}
				</div>
				
				<Svg name={"arrow_drop_down"} color={"var(--color-pck)"}/>
				
			</div>
			
			{open?
			 <div className={"OpenBoxContainer"} style={background?{backgroundColor: background}:null} direction={`${dir}`}>
				<div className={" _dsplFlx"}>
					<input className={"OpenBoxInput"} placeholder="search" onChange={handleInputSearch} ref={inputRef}/>
					<div className="icon_close" onClick={clearInputSearch}>
						<Svg name={"cancel"} color={"var(--color-pck)"} size={18}/>
					</div>
				</div>
				<div className={"separator"} />
				<div  className={" monthList"} style={{}}>
					{list.map((elm, wwInd)=>{
						let mnt = elm.label;

						if(!mnt){
							return null;
						}

						return (
							<div 
								key={mnt + "_" +wwInd}  
								className={"filter_month_item _dsplFlx"} 
								onClick={()=>handleSelection(elm)}
							>
								
								<div className="lbl tr_bar_90 " style={{marginLeft:5}}>
									{mnt}
								</div>
								
							</div>
						)
					})}
				</div>
			</div>
			:null}
		
			
		</div>
		
	);
};

export default DropDwnPickerSearchComponent;
