import React, { useEffect, useState, useRef } from "react";



import { getStore, updStore, gen16CodeId,  ObjectKeys,  hasWritePrivilege, parseDateMMDDYYYY } from "../../../stores/Utils";

import {CalendarPicker_Cmpt, DropDwnPicker_Cmpt, DropDwnSearchPicker_Cmpt, SearchInput_Cmpt, SvgIcon_Cmpt } from "../../../components";

import { OpenModal } from "../../../components/DialogHRM";

import "./dashboard.css"
import {  DoInventoryByLoc_Cmpt, InventoryLocationItem_Cmpt, LocationViews_Cmpt } from "..";
import {   getProductByQuery, scan_location_inventory, scan_location_production, } from "../services/server_fetching";
import { get_balances_by_type } from "../../CuentasContables/services/server_fetching";

import { LocationsLabelsPdf } from "../services/export_service";
import DropDwnPickerSearchComponent from "../../../components/DropDwnPickerSearch";



const SearchInput = SearchInput_Cmpt();

const Svg = SvgIcon_Cmpt();

const InventoryLocationItem = InventoryLocationItem_Cmpt();
const DropDwnPicker = DropDwnPicker_Cmpt();

const CalendarModalPicker = CalendarPicker_Cmpt();

const LocationViews = LocationViews_Cmpt();

const DoInventoryByLoc = DoInventoryByLoc_Cmpt();



const InventoryDashboard  = ({ data, elmId, updObs }) => {
	const [initialize, setInitialize] = useState(false);
	const [, set_obs] = useState(0);
	const [loading, set_loading] = useState(false);




	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			set_obs(gen16CodeId())
			scan_location_production(loadInventLoc);
			get_balances_by_type("global_accounts","global_account_params",updObs);
		}
	});


	const loadInventLoc =  (v) => {

		cb_result()
	}


	


	const handleChange =  (v) => {
		!loading && set_loading(true)
	}


	const handle_search_movement =  (v) => {
		set_loading(true)
		scan_location_inventory(cb_result)
	}


	const handle_getall_movement =  (v) => {
		scan_location_inventory(cb_result);
	}

	const cb_result = async (f, v) => {
		set_obs(gen16CodeId())
		set_loading(false);
	};


	const openAddArea =  () => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		dataModal["content"] = 
			<LocationViews />
		
		OpenModal(dataModal);
	}


	const openDoINv =  () => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		dataModal["content"] = 
			<DoInventoryByLoc />
		OpenModal(dataModal);
	}



	


	const openUpdateView =  (v) => {
		
		
	}


	const updlocDrop =  (f,v) => {
		updStore(f,v);
		handle_search_movement();
	}

	const confirmCalendar = (v) => {
		// updLoading(true);
		if(v?.initDate && v?.lastDate ){
			let nv = {...v};
			nv.initDate = nv.initDate -100;
			nv.lastDate = nv.lastDate + 86380000;
			updStore("date_range_inv_loc",nv);
		}
		handle_search_movement();
	}

	const clearCalendar = (v) => {
		updStore("date_range_inv_loc",{});
		handle_search_movement();
	}
	
    const openCalendar = () => {
        let modal_data = {};
        modal_data["zIndex"] = 950;
        modal_data["height"] = "80vh";
        // data['observeResize']=true;
        modal_data["props"] = { minHeight: "1vh", overlay: true };
        modal_data["content"] = 
			<CalendarModalPicker 
				onConfirm={confirmCalendar} 
				onClear={clearCalendar} 
				init={getStore("date_range_inv_loc")?.initDate}
				last={getStore("date_range_inv_loc")?.lastDate}
				isRange={true}
				hasClear={true}
				colors={ {
					"--calendar-primary-color":"var(--hrm_palette-blue-purple)",
					"--calendar-primary-backcolor":"var(--primary-light)",
					"--calendar-light-backcolor":"var(--hrm_palette-general-background-b)",
					"--calendar-primary-hover-backcolor":"var(--hrm_palette-blue-purple_100)",

					"--calendar-light-300":"var(--disabled)",
					"--calendar-light-200":"var(--dark-800)",
					"--calendar-light-100":"var(--dark-900)",
					"--calendar-dark-800":"var(--hrm_palette-blue-purple_100)",
					"--calendar-white-100":"var(--light-100)",
					"--calendar-white":"var(--dark-700)",
					
					"--calendar-selected_lbl_color":"var(--light-400)",
					
					"--calendar-selected_lbl_color":"var(--primary-blue--color-30)",
				  }}
			/>
        
        OpenModal(modal_data);
	}
	

	let dateRangeString = getStore("date_range_inv_loc")?.initDate && parseDateMMDDYYYY(getStore("date_range_inv_loc")?.initDate)  + " - " +parseDateMMDDYYYY(getStore("date_range_inv_loc")?.lastDate);

	
	

	return (

	<div className="inv_loc_dash">
		<div className="accounts_header">
			<h2>Inventory and Locations</h2>
			<div className="_dsplFlx ">
				
				{hasWritePrivilege()?
				<p className="btn_lkjh addBtn purple" onClick={openAddArea} >
					Locations
				</p>
				:null}
				
				{hasWritePrivilege()?
				<p className="btn_lkjh addBtn purple" onClick={openDoINv} >
					Inventory By Location
				</p>
				:null}
			</div>
		</div>
		<div className="_dsplFlx " style={{marginTop:14}} >
			<SearchInput
				placeholder={"Buscar ...."} 
				width={560}
				obs={set_obs}
				fetchData={handle_search_movement}
				loading={loading}
				change={handleChange}
				callempty={handle_getall_movement}
				keyFlds={"searchLocationQry"}
			/>
			<div className="_dsplFlx spaceAround"  style={{padding: 3}}>
				<DropDwnPicker 
					init={getStore("locationId2F")}
					lbl_empty={"Location"} 
					list={getStore("location_drpdwn") || []} 
					onSelect={(e)=>updlocDrop("locationId2F",e.id)}
					background={"#f9f9f9"}
					color={"var(--hrm_palette-blue-purple)"}
					direction={"left"}
					width={"220px"}
				/>
			</div>
			<div className="_dsplFlx spaceAround"  style={{padding: 3}}>
				<DropDwnPickerSearchComponent 
					init={getStore("productId2F")}
					lbl_empty={"Product"} 
					func={getProductByQuery} 
					onSelect={(e)=>updlocDrop("productId2F",e.id)}
					background={"#f9f9f9"}
					color={"var(--hrm_palette-blue-purple)"}
					direction={"left"}
					width={"280px"}
				/>
			</div>
			<div className={"filter_date_btn _dsplFlx"} onClick={openCalendar}>
				<div className="lbl date">
						{dateRangeString || "Fecha"}
				</div>
				<Svg name={"calendar"} color={"#66666"}/>
			</div>
			<div className="flexSpace"/>
			<div className="_dsplFlx ">
				<div className="total_comprobante_title">
					No: 
				</div>
				<div className="total_comprobante gray">
					<span>
						{ObjectKeys(getStore("inv_location_list"))?.length}
					</span>
				</div>
			</div>
		</div>
		<div className="_dsplFlx hdr_bar purple" style={{marginTop:10}}>
			<div className="_dsplFlx tr_bar_90 ">
				
				<div className=" tr_bar_20 centerBx" >
					Fecha
				</div>
				<div className=" tr_bar_20 centerBx">
					Location
				</div>
				<div className=" tr_bar_20 centerBx">
					Code
				</div>
				<div className=" tr_bar_20 centerBx">
					Product
				</div>
			</div>
			<div className="flexSpace"/>
			<div className="icon tr_bar_5" >
			</div>	
		</div>
		<div className="movements_container scollVh">
			{getStore("inv_location_list") && ObjectKeys(getStore("inv_location_list"))?.map(cid=>{
				return (
					<InventoryLocationItem 
						data={getStore("inv_location_list")[cid]} 
						elmId={cid} 
						key={cid}
						openUpdateView={openUpdateView}
						handleRefreshAll={handle_search_movement}
					/>
				)
			})}
		</div>
	</div>
	);
};

export default InventoryDashboard;


